const crypto = require('crypto');

const secret  = $env.JWT_SECRET || '__REDACTED_JWT_SECRET__';
const ttlHrs  = parseInt($env.JWT_TTL_HOURS || '24', 10);

const b64url = (buf) =>
  Buffer.from(buf)
    .toString('base64')
    .replace(/=+$/g, '')
    .replace(/\+/g, '-')
    .replace(/\//g, '_');

const now    = Math.floor(Date.now() / 1000);
const header = { alg: 'HS256', typ: 'JWT' };
const payload = {
  sub:   $json.user_id,
  email: $json.email,
  iat:   now,
  exp:   now + ttlHrs * 3600
};

const h   = b64url(JSON.stringify(header));
const p   = b64url(JSON.stringify(payload));
const sig = b64url(crypto.createHmac('sha256', secret).update(`${h}.${p}`).digest());
const token = `${h}.${p}.${sig}`;

return [{ json: { token, user_id: $json.user_id, email: $json.email } }];
